function openQuote(id){const row=records('quotes').find(item=>rowId(item,'Quote ID','quoteId')===id);if(!row){toast('Saved quote was not found in the current business pack.',true);return false;}const savedLines=(row.lines||[]).map(line=>({quoteLineId:v(line,'Quote Line ID','quoteLineId')||newId('QUOTE-LINE'),description:v(line,'Description','description'),quantity:num(v(line,'Quantity','quantity')),unit:v(line,'Unit','unit'),unitPrice:num(v(line,'Unit Price','unitPrice')),priceSource:v(line,'Price Source','priceSource'),priceStatus:v(line,'Price Status','priceStatus')}));const rawTiers=v(row,'Tiers','tiers');const savedTiers=Array.isArray(rawTiers)&&rawTiers.length===3?rawTiers.map((t,ti)=>({name:String((t&&t.name)||['Good','Better','Best'][ti]).slice(0,24),description:String((t&&t.description)||''),items:Array.isArray(t&&t.items)?t.items.map(line=>({quoteLineId:v(line,'Quote Line ID','quoteLineId')||newId('QUOTE-LINE'),description:v(line,'Description','description'),quantity:num(v(line,'Quantity','quantity')),unit:v(line,'Unit','unit'),unitPrice:num(v(line,'Unit Price','unitPrice')),priceSource:v(line,'Price Source','priceSource'),priceStatus:v(line,'Price Status','priceStatus')})):[]})):null;const tierMode=!!savedTiers;const savedTotal=num(v(row,'Total','total'));const calculatedTotal=savedLines.reduce((sum,line)=>sum+num(line.quantity)*num(line.unitPrice),0);if(tierMode){const betterTotal=savedTiers[1].items.reduce((sum,line)=>sum+num(line.quantity)*num(line.unitPrice),0);if(savedTotal>0&&Math.abs(savedTotal-betterTotal)>0.01){toast(`Saved quote protection stopped an inconsistent draft from opening. Stored total ${money(savedTotal)} does not match the Better tier ${money(betterTotal)}. Nothing was changed.`,true);return false;}}else{if(savedTotal>0&&!savedLines.length){toast('This saved quote has a total but its saved line items did not load. The draft was not opened or rebuilt. Refresh the Business Office and try again.',true);return false;}if(savedTotal>0&&Math.abs(savedTotal-calculatedTotal)>0.01){toast(`Saved quote protection stopped an inconsistent draft from opening. Stored total ${money(savedTotal)} does not match loaded lines ${money(calculatedTotal)}. Nothing was changed.`,true);return false;}}state.page='quotes';state.quote={quoteId:id,quoteNumber:v(row,'Quote Number','quoteNumber'),customerId:v(row,'Customer ID','customerId'),projectTitle:v(row,'Project Title','projectTitle'),scope:v(row,'Scope','scope'),measurementNotes:v(row,'Measurement Notes','measurementNotes'),revision:num(v(row,'Revision','revision')),lines:tierMode?[]:savedLines,tierMode,tiers:savedTiers,savedTotal,loadedSavedTotal:savedTotal,loadedRevision:num(v(row,'Revision','revision')),loadedAt:new Date().toISOString(),hydrationComplete:true,savedLineSnapshot:JSON.parse(JSON.stringify(tierMode?savedTiers:savedLines)),savedScopeSnapshot:v(row,'Scope','scope')||'',savedMeasurementSnapshot:v(row,'Measurement Notes','measurementNotes')||''};renderQuotes();toast(`Opened saved revision ${state.quote.revision||1} at ${money(savedTotal)}${tierMode?' (Better tier total)':''}. Quantities may be adjusted; AI updates cannot replace this revision.`);return true;}


function renderMeasure(){
  const inQuoteWorkspace=state.page==='quotes',linkedQuoteId=inQuoteWorkspace?(state.quote?.quoteId||''):'';
  const jobs=records('jobs'),quotes=records('quotes'),allMeasurements=records('measurements'),measurements=inQuoteWorkspace?allMeasurements.filter(row=>linkedQuoteId&&String(v(row,'Quote ID'))===linkedQuoteId):allMeasurements;
  const title=inQuoteWorkspace?'Quote Builder — Photos & Measure':'Measure',description=inQuoteWorkspace?'Capture quote photos, direct dimensions, device measurements and estimate-grade site notes without leaving this quote.':'Capture direct, device, reference-scaled and estimate-grade dimensions online or offline.';
  const tools=inQuoteWorkspace?`<button id="backToQuoteButton" class="secondary">← Back to Quote</button><button id="measureVoiceButton" class="secondary">Speak measurement</button>`:`<button id="measureVoiceButton" class="secondary">Speak measurement</button>`;
  $('mainContent').innerHTML=pageHead(title,description,tools)+`<div class="grid"><section class="card span5"><h2>Measurement capture</h2>${inQuoteWorkspace&&!linkedQuoteId?'<div class="notice">Save the quote draft first to permanently link measurements. Photos and notes can still be captured now.</div>':''}<form id="measurementForm"><label>Name</label><input name="measurementName" id="measurementName" required placeholder="North wall width"><div class="two"><div><label>Job</label><select name="jobId">${optionRows(jobs,['Job ID'],row=>`${v(row,'Job Number')} — ${v(row,'Project Title')}`,'No job')}</select></div><div><label>Quote</label><select name="quoteId" id="measurementQuote">${optionRows(quotes,['Quote ID'],row=>v(row,'Project Title'),'No saved quote')}</select></div></div><div class="three"><div><label>Value</label><input name="value" id="measurementValue" type="number" step="0.001" required></div><div><label>Unit</label><select name="unit" id="measurementUnit"><option>ft</option><option>in</option><option>m</option><option>cm</option><option>sq ft</option><option>cu yd</option><option>degrees</option></select></div><div><label>Type</label><select name="measurementType"><option>Length</option><option>Width</option><option>Height</option><option>Area</option><option>Volume</option><option>Slope</option><option>Count</option></select></div></div><label>Method</label><select name="method" id="measurementMethod"><option>Direct measurement</option><option>Device measured</option><option>Reference-scaled estimate</option><option>Visual estimate</option><option>User confirmed</option><option>Needs verification</option></select><div class="two"><div><label>Known reference size</label><input name="referenceSize" type="number" step="0.001"></div><div><label>Reference unit</label><input name="referenceUnit" placeholder="in, ft, cm"></div></div><label>Notes / spoken context</label><textarea name="notes" id="measurementNotes" placeholder="Point A to B, photo angle, openings, assumptions…"></textarea><div class="actions"><button>Save measurement</button><button type="button" class="secondary" id="measurePhotoButton">Add quote/site photo</button><input id="measurePhotoInput" class="hidden" type="file" accept="image/*" capture="environment"></div></form><div class="notice warn">Visual and reference-scaled estimates are never treated as verified. Critical dimensions and ordered materials require direct or device confirmation.</div></section><section class="card span7"><h2>${inQuoteWorkspace?'Measurements for this quote':'Measurement worksheet'}</h2><div class="list">${measurements.length?measurements.slice(0,150).map(row=>`<div class="row"><div class="row-top"><strong>${esc(v(row,'Measurement Name'))}</strong>${pill(v(row,'Method'),String(v(row,'Method')).includes('estimate')?'pending':'good')}</div><small>${esc(v(row,'Value'))} ${esc(v(row,'Unit'))} · ${esc(v(row,'Measurement Type'))} · ${esc(v(row,'Confidence'))}${v(row,'Job ID')?' · '+esc(jobName(v(row,'Job ID'))):''}</small><p>${esc(v(row,'Notes'))}</p></div>`).join(''):empty(inQuoteWorkspace?'No measurements are linked to this saved quote yet.':'No measurements captured.')}</div></section></div>`;
  if(inQuoteWorkspace)$('backToQuoteButton').onclick=renderQuotes;
  $('measureVoiceButton').onclick=toggleVoice;
  if(linkedQuoteId&&$('measurementQuote'))$('measurementQuote').value=linkedQuoteId;
  $('measurePhotoButton').onclick=()=>$('measurePhotoInput').click();$('measurePhotoInput').onchange=event=>handleAttachmentFiles(event.target.files,inQuoteWorkspace?'Quote':'Measurement',inQuoteWorkspace?(linkedQuoteId||'LOCAL-QUOTE'):'LOCAL-MEASUREMENT','Internal');
  bindForm('measurementForm',async(data,form)=>{const id=newId('MEASUREMENT'),method=data.method,confidence=method==='Visual estimate'||method==='Reference-scaled estimate'?'Needs verification':'User confirmed',quoteId=data.quoteId||linkedQuoteId,record={'Measurement ID':id,'Business ID':state.businessId,'Job ID':data.jobId,'Quote ID':quoteId,'Measurement Name':requireValue(data.measurementName,'Measurement name is required.'),'Measurement Type':data.measurementType,'Value':num(data.value),'Unit':data.unit,'Method':method,'Confidence':confidence,'Reference Size':num(data.referenceSize),'Reference Unit':data.referenceUnit,'Notes':data.notes,'Status':'Active','Created By':state.snapshot.user.userId,'Created Time':now(),'Updated Time':now(),'Record Version':1};await queueOperation('SAVE_MEASUREMENT','Measurement',id,{measurementId:id,...data,quoteId,confidence},{collection:'measurements',record,idKeys:['Measurement ID']});form.reset();toast(`${method} saved${confidence==='Needs verification'?' and flagged for verification':''}.`);renderMeasure();});
}

