function renderSchedule(){const events=records('scheduleEvents').sort((a,b)=>new Date(v(a,'Start Time'))-new Date(v(b,'Start Time'))),jobs=records('jobs'),users=activeRows(records('users'));$('mainContent').innerHTML=pageHead('Schedule','Assign work, appointments, crews and focus time while preserving the same job records.',`<button id="snowTriggerButton" class="primary" hidden>Snow day - create snow jobs</button> <button id="readScheduleButton" class="secondary">Read schedule</button>`)+`<div class="grid"><section class="card span5"><h2>Add schedule event</h2><form id="scheduleForm"><label>Title</label><input name="title" required><label>Job</label><select name="relatedRecordId">${optionRows(jobs,['Job ID'],row=>`${v(row,'Job Number')} — ${v(row,'Project Title')}`,'No linked job')}</select><label>Assigned user</label><select name="assignedUserId">${optionRows(users,['User ID'],row=>v(row,'Display Name','Email'),'Unassigned')}</select><div class="two"><div><label>Start</label><input name="startTime" type="datetime-local" required></div><div><label>End</label><input name="endTime" type="datetime-local"></div></div><label>Location</label><input name="location"><label>Notes</label><textarea name="notes"></textarea><div class="actions"><button>Save schedule</button></div></form></section><section class="card span7"><h2>Upcoming</h2><div class="list calendar-list">${events.length?events.slice(0,80).map(row=>{const linkedJobId=v(row,'Related Record ID');const showOnMyWay=(window.H38CustomerComms&&window.H38CustomerComms.onMyWayEnabled())&&linkedJobId;return `<div class="row"><div class="row-top"><strong>${esc(v(row,'Title'))}</strong>${pill(v(row,'Status'))}</div><small>${dateTime(v(row,'Start Time'))}–${v(row,'End Time')?dateTime(v(row,'End Time')):'open'} · ${esc(userName(v(row,'Assigned User ID')))} · ${esc(v(row,'Location'))}</small>${showOnMyWay?`<div class="row-actions"><button class="secondary" data-schedule-on-my-way="${esc(linkedJobId)}">Text: On My Way</button></div>`:''}</div>`;}).join(''):empty('Nothing scheduled.')}</div></section></div>`;$('readScheduleButton').onclick=readMyDay;
document.querySelectorAll('[data-schedule-on-my-way]').forEach(b=>b.onclick=()=>{if(window.H38CustomerComms)window.H38CustomerComms.sendOnMyWay(b.dataset.scheduleOnMyWay).catch(e=>toast(e.message||String(e),true));});
(function(){var customers=records('customers'),snowCustomers=customers.filter(function(c){return v(c,'Snow Service')==='Yes';});var btn=$('snowTriggerButton');if(!btn)return;if(!snowCustomers.length){btn.hidden=true;return;}btn.hidden=false;
btn.onclick=function(){var inches=prompt('How many inches of snow fell?','3');if(inches===null)return;var amt=parseFloat(inches);if(!isFinite(amt)||amt<=0){toast('Enter a valid snowfall amount.',true);return;}
if(!confirm('Create snow removal jobs for '+snowCustomers.length+' customer'+(snowCustomers.length===1?'':'s')+' at '+amt+' inches?'))return;
btn.disabled=true;btn.textContent='Creating jobs...';var created=0;var today=new Date().toISOString().slice(0,10);var queue=[];
snowCustomers.forEach(function(c){var cid=rowId(c,'Customer ID','customerId');var jobId='SNOW-'+today+'-'+cid;
var exists=records('jobs').some(function(j){return rowId(j,'Job ID','jobId')===jobId;});if(exists)return;
var record={'Job ID':jobId,'Business ID':state.businessId,'Job Number':jobId,'Customer ID':cid,'Project Title':'Snow removal - '+v(c,'Customer Name','name'),'Service':'Snow removal','Snowfall Inches':amt,'Equipment':v(c,'Snow Equipment'),'Time Constraint':v(c,'Snow Time Constraint'),'Snow Notes':v(c,'Snow Notes'),'Status':'Scheduled','Created Time':now(),'Updated Time':now(),'Record Version':1};
queue.push(queueOperation('SAVE_JOB','Job',jobId,{jobId:jobId},{collection:'jobs',record:record,idKeys:['Job ID']}).then(function(){created++;}));});
Promise.all(queue).then(function(){btn.disabled=false;btn.textContent='Snow day - create snow jobs';toast(created+' snow job'+(created===1?'':'s')+' created for '+amt+' inches.');renderSchedule();});};})();bindForm('scheduleForm',async(data,form)=>{const id=newId('SCHEDULE'),record={'Schedule Event ID':id,'Business ID':state.businessId,'Event Type':'Job','Title':requireValue(data.title,'Title is required.'),'Related Record Type':'Job','Related Record ID':data.relatedRecordId,'Assigned User ID':data.assignedUserId,'Start Time':data.startTime,'End Time':data.endTime,'Location':data.location,'Status':'Scheduled','Notes':data.notes,'Created Time':now(),'Updated Time':now(),'Record Version':1};await queueOperation('SAVE_SCHEDULE','Schedule Event',id,{scheduleEventId:id,...data,relatedRecordType:'Job',status:'Scheduled'},{collection:'scheduleEvents',record,idKeys:['Schedule Event ID']});try{const linkedJob=records('jobs').find(r=>rowId(r,'Job ID','jobId')===data.relatedRecordId);if(linkedJob&&/^(lead|quoted|approved)$/i.test(String(v(linkedJob,'Status')||''))){const updatedJob={...linkedJob,'Status':'Scheduled','Updated Time':now(),'Record Version':num(v(linkedJob,'Record Version','recordVersion'))+1};delete updatedJob.__localPending;await queueOperation('SAVE_JOB','Job',data.relatedRecordId,{jobId:data.relatedRecordId,...updatedJob},{collection:'jobs',record:updatedJob,idKeys:['Job ID']});}}catch(statusError){toast('Schedule saved, but the job status could not be set to Scheduled. Update it from the Jobs list.',true);}form.reset();toast('Schedule event queued.');renderSchedule();});}

function renderMessages(){const conversations=records('conversations'),messages=records('messages'),selected=state.selectedConversation||rowId(conversations[0],'Conversation ID');state.selectedConversation=selected;const visibleMessages=messages.filter(row=>v(row,'Conversation ID')===selected).sort((a,b)=>String(v(a,'Created Time')).localeCompare(String(v(b,'Created Time'))));const tabs=['internal','email','sms','portal',...(window.H38_COMMUNICATIONS?.visible?.()?['receptionist']:[])];$('mainContent').innerHTML=pageHead('Communications','Internal chat, email management, business text drafts and customer portal messages remain clearly separated.')+`<div class="tabs">${tabs.map(tab=>`<button data-message-tab="${tab}" class="${state.messageTab===tab?'active':''}">${tab==='internal'?'Internal':tab==='email'?'Email':tab==='sms'?'Customer texts':tab==='portal'?'Portal':'Receptionist'}</button>`).join('')}</div>${state.messageTab==='internal'?`<div class="thread-layout"><section class="card thread-list"><h2>Business conversations</h2><div class="list">${conversations.length?conversations.map(row=>`<div class="row"><div class="row-top"><strong>${esc(v(row,'Subject'))}</strong>${pill(v(row,'Conversation Type'))}</div><div class="row-actions"><button data-conversation="${esc(rowId(row,'Conversation ID'))}">Open</button></div></div>`).join(''):empty('No conversations.')}</div><hr><form id="conversationForm"><label>New channel or group</label><input name="subject" required placeholder="Crew, office, project…"><select name="conversationType"><option>Channel</option><option>Group</option><option>Direct</option></select><div class="actions"><button>Create</button></div></form></section><section class="card"><h2>${esc(v(conversations.find(row=>rowId(row,'Conversation ID')===selected),'Subject')||'Conversation')}</h2><div class="message-list">${visibleMessages.length?visibleMessages.map(row=>`<div class="message ${v(row,'Sender User ID')===state.snapshot.user.userId?'mine':''}">${esc(v(row,'Body'))}<small>${esc(userName(v(row,'Sender User ID')))} · ${dateTime(v(row,'Created Time'))}</small></div>`).join(''):empty('No messages yet.')}</div><form id="messageForm"><label>Message</label><textarea name="body" required placeholder="Write freely inside this business…"></textarea><div class="actions"><button>Send internally</button><button type="button" class="secondary" id="voiceMessageButton">Dictate</button></div></form></section></div>`:state.messageTab==='email'?emailDraftView():state.messageTab==='sms'?smsDraftView():state.messageTab==='portal'?portalDraftView():(window.H38_COMMUNICATIONS?.render?.()||'<section class="card"><p>Receptionist test is unavailable.</p></section>')}`;document.querySelectorAll('[data-message-tab]').forEach(button=>button.onclick=()=>{state.messageTab=button.dataset.messageTab;renderMessages();});document.querySelectorAll('[data-conversation]').forEach(button=>button.onclick=()=>{state.selectedConversation=button.dataset.conversation;renderMessages();});if(state.messageTab==='internal'){bindForm('conversationForm',async(data,form)=>{const id=newId('CONVERSATION'),record={'Conversation ID':id,'Business ID':state.businessId,'Conversation Type':data.conversationType,'Subject':requireValue(data.subject,'Subject is required.'),'Participant IDs JSON':JSON.stringify([state.snapshot.user.userId]),'Status':'Active','Created Time':now(),'Updated Time':now(),'Record Version':1};await queueOperation('CREATE_CONVERSATION','Conversation',id,{conversationType:data.conversationType,subject:data.subject,participantUserIds:[state.snapshot.user.userId]},{collection:'conversations',record,idKeys:['Conversation ID']});state.selectedConversation=id;form.reset();renderMessages();});bindForm('messageForm',async(data,form)=>{if(!state.selectedConversation)throw new Error('Create or select a conversation.');const id=newId('MESSAGE'),record={'Message ID':id,'Business ID':state.businessId,'Conversation ID':state.selectedConversation,'Sender User ID':state.snapshot.user.userId,'Message Type':'Text','Body':requireValue(data.body,'Message is required.'),'Status':'Sent Internal','Created Time':now(),'Record Version':1};await queueOperation('SEND_INTERNAL_MESSAGE','Message',id,{conversationId:state.selectedConversation,body:data.body},{collection:'messages',record,idKeys:['Message ID']});form.reset();renderMessages();});$('voiceMessageButton').onclick=toggleVoice;}else if(state.messageTab==='email')bindEmailForm();else if(state.messageTab==='sms')bindSmsForm();else if(state.messageTab==='portal')bindPortalForm();else window.H38_COMMUNICATIONS?.mount?.();}
;

