function emailDraftView(){const threads=records('emailThreads');return`<div class="grid"><section class="card span5"><h2>Email draft</h2><div class="notice warn">Email provider: ${esc(providerStatus('email'))}. Drafts stay internal until you tap Send on a draft.</div><form id="emailForm"><label>To</label><input name="toAddress" type="email" required><label>Subject</label><input name="subject"><label>Message</label><textarea name="body" required></textarea><div class="actions"><button>Save email draft</button></div></form></section><section class="card span7"><h2>Email threads</h2><div class="list" id="h38EmailThreadList">${threads.length?threads.map(row=>{var actions=(window.H38EmailSend&&window.H38EmailSend.threadRowActions)?window.H38EmailSend.threadRowActions(row):'';return`<div class="row"><div class="row-top"><strong>${esc(v(row,'Subject'))}</strong>${pill(v(row,'Status'))}</div><small>${esc(v(row,'Mailbox')||'Unconnected mailbox')} · ${dateTime(v(row,'Last Message Time'))}</small>${actions}</div>`;}).join(''):empty('No email threads captured yet.')}</div></section></div>`;}
function bindEmailForm(){bindForm('emailForm',async(data,form)=>{const id=newId('EMAIL-MESSAGE'),threadId=newId('EMAIL-THREAD'),thread={'Email Thread ID':threadId,'Business ID':state.businessId,'Provider':'Provider Neutral','Subject':data.subject,'Status':'Draft','Last Message Time':now(),'Record Version':1},message={'Email Message ID':id,'Business ID':state.businessId,'Email Thread ID':threadId,'Direction':'Outbound Draft','To Addresses JSON':JSON.stringify([data.toAddress]),'Subject':data.subject,'Body Preview':data.body,'Status':'Draft — Not Sent','Created Time':now(),'Record Version':1};await queueOperation('SAVE_EMAIL_DRAFT','Email Message',id,{emailThreadId:threadId,...data},{collection:'emailThreads',record:thread,idKeys:['Email Thread ID']});state.snapshot.emailMessages.unshift(message);form.reset();if(window.H38Flow)window.H38Flow.showNextStep({title:'Email draft "'+data.subject+'" saved.',next:'Review it in the threads list, then tap Send when ready.',actions:[{label:'View drafts',primary:true,handler:function(){renderMessages();}}],id:'h38EmailDraftSaved',signature:'email-draft-'+threadId});else toast('Email draft saved. Tap Send when ready.');renderMessages();});if(window.H38EmailSend&&window.H38EmailSend.bindThreadActions){var el=document.getElementById('h38EmailThreadList')||document;window.H38EmailSend.bindThreadActions(el);}}
function smsDraftView(){const threads=records('smsThreads');return`<div class="grid"><section class="card span5"><h2>Customer text draft</h2><div class="notice warn">Business SMS provider: ${esc(providerStatus('sms'))}. Consent and STOP suppression are required before any future send.</div><form id="smsForm"><label>Customer number</label><input name="toNumber" type="tel" required><label>Consent status</label><select name="consentStatus"><option>Unknown</option><option>Consented</option><option>Opted Out</option></select><label>Message</label><textarea name="body" required></textarea><div class="actions"><button>Save text draft</button><button type="button" class="secondary" id="smsRequestSendButton">Request send</button></div></form></section><section class="card span7"><h2>Customer text threads</h2><div class="list">${threads.length?threads.map(row=>`<div class="row"><div class="row-top"><strong>${esc(v(row,'Customer Number'))}</strong>${pill(v(row,'Status'))}</div><small>Consent: ${esc(v(row,'Consent Status'))} · ${dateTime(v(row,'Last Message Time'))}</small></div>`).join(''):empty('No customer text threads.')}</div></section>${(window.H38Sms&&H38Sms.templatesCard)?H38Sms.templatesCard():''}${(window.H38Sms&&H38Sms.queueCard)?H38Sms.queueCard():''}${(window.H38SmsSetup&&H38SmsSetup.setupCard)?H38SmsSetup.setupCard():''}</div>`;}
function bindSmsForm(){bindForm('smsForm',async(data,form)=>{const id=newId('SMS-MESSAGE'),threadId=newId('SMS-THREAD'),thread={'SMS Thread ID':threadId,'Business ID':state.businessId,'Provider':'Provider Neutral','Customer Number':data.toNumber,'Consent Status':data.consentStatus,'Status':'Draft','Last Message Time':now(),'Record Version':1};await queueOperation('SAVE_SMS_DRAFT','SMS Message',id,{smsThreadId:threadId,...data},{collection:'smsThreads',record:thread,idKeys:['SMS Thread ID']});form.reset();if(window.H38Flow)window.H38Flow.showNextStep({title:'Text draft saved.',next:'Tap "Request send" to queue it for owner approval.',actions:[{label:'View drafts',primary:true,handler:function(){renderMessages();}}],id:'h38SmsDraftSaved',signature:'sms-draft-'+threadId});else toast('Text draft saved. Tap "Request send" to queue it for approval.');renderMessages();});var smsReqBtn=document.getElementById('smsRequestSendButton');if(smsReqBtn)smsReqBtn.onclick=async function(){try{if(!window.H38Sms)throw new Error('SMS module is still loading. Try again in a moment.');var f=document.getElementById('smsForm'),fd=new FormData(f),d=Object.fromEntries(fd.entries());var r=await window.H38Sms.sendSms({to:d.toNumber,body:d.body,consentStatus:d.consentStatus,purpose:'Customer text'});toast('Queued for owner approval ('+r.segments+' segment(s)). Nothing sent yet.');renderMessages();}catch(err){toast(err.message||String(err),true);}};if(window.H38Sms&&H38Sms.bindTemplatesUI)H38Sms.bindTemplatesUI();if(window.H38SmsSetup&&H38SmsSetup.bindSetupUI)H38SmsSetup.bindSetupUI();if(window.H38SmsTriggers){H38SmsTriggers.runDaily().then(function(r){if(r&&r.ran){var n=((r.reminders&&r.reminders.drafted)||0)+((r.followUps&&r.followUps.drafted)||0);if(n>0)toast('Hank drafted '+n+' text(s) for your approval.');}}).catch(function(){});}}
function portalDraftView(){const threads=records('portalThreads'),customers=records('customers');return`<div class="grid"><section class="card span5"><h2>Portal message draft</h2><form id="portalForm"><label>Customer</label><select name="customerId">${optionRows(customers,['Customer ID'],row=>v(row,'Customer Name'),'Select customer')}</select><label>Subject</label><input name="subject"><label>Message</label><textarea name="body" required></textarea><div class="actions"><button>Prepare portal message</button></div></form></section><section class="card span7"><h2>Portal conversations</h2><div class="list" id="h38PortalThreadList">${threads.length?threads.map(row=>{var st=String(v(row,'Status')||'');var rel=(st==='Ready to Release')?`<div class="row-actions"><button type="button" data-portal-release="${esc(v(row,'Portal Thread ID'))}">Release to customer portal</button></div>`:'';return`<div class="row"><div class="row-top"><strong>${esc(v(row,'Subject'))}</strong>${pill(v(row,'Status'))}</div><small>${esc(customerName(v(row,'Customer ID')))}</small>${rel}</div>`;}).join(''):empty('No portal conversations.')}</div></section></div>`;}
function bindPortalForm(){bindForm('portalForm',async(data,form)=>{const id=newId('PORTAL-MESSAGE'),threadId=newId('PORTAL-THREAD'),thread={'Portal Thread ID':threadId,'Business ID':state.businessId,'Customer ID':data.customerId,'Subject':data.subject,'Status':'Ready to Release','Created Time':now(),'Updated Time':now(),'Record Version':1};await queueOperation('SAVE_PORTAL_MESSAGE','Portal Message',id,{portalThreadId:threadId,...data},{collection:'portalThreads',record:thread,idKeys:['Portal Thread ID']});form.reset();if(window.H38Flow)window.H38Flow.showNextStep({title:'Portal message prepared.',next:'Release it to the customer portal when ready.',actions:[{label:'View messages',primary:true,handler:function(){renderMessages();}}],id:'h38PortalPrepared',signature:'portal-'+threadId});else toast('Portal message prepared. Tap Release when ready.');renderMessages();});bindPortalReleaseActions();}
function bindPortalReleaseActions(){var root=document.getElementById('h38PortalThreadList')||document;root.querySelectorAll('[data-portal-release]').forEach(function(b){if(b.dataset.h38Bound)return;b.dataset.h38Bound='1';b.addEventListener('click',async function(){var tid=b.getAttribute('data-portal-release');var rows=[];try{rows=records('portalThreads')||[];}catch(e){}var row=null;for(var i=0;i<rows.length;i++){if(String(v(rows[i],'Portal Thread ID'))===tid){row=rows[i];break;}}if(!row){toast('That message is gone.',true);return;}var ok=window.H38Flow?await window.H38Flow.confirm({title:'Release to customer portal?',message:'The customer will see this message in their portal.',okLabel:'Release',cancelLabel:'Cancel'}):true;if(!ok)return;var rec=Object.assign({},row,{'Status':'Released','Updated Time':now(),'Record Version':(Number(v(row,'Record Version'))||0)+1});var hist='';try{if(window.H38Flow&&window.H38Flow.pushStatusHistory)hist=window.H38Flow.pushStatusHistory(row,row['Status'],'Released');}catch(e){}if(hist)rec['Status History']=hist;await queueOperation('PORTAL_RELEASE','Portal Thread',tid,{threadId:tid},{collection:'portalThreads',record:rec,idKeys:['Portal Thread ID']});if(window.H38Flow)window.H38Flow.showNextStep({title:'Message released to the customer portal.',next:'Nothing further needed.',actions:[{label:'View messages',handler:function(){renderMessages();}}],id:'h38PortalReleased',signature:'portal-rel-'+tid});else toast('Message released.');renderMessages();});});}
function providerStatus(type){const row=records('providers').find(item=>String(v(item,'Provider Type')).toLowerCase()===type);const status=v(row,'Connection Status')||'Not Connected';const s=String(status).toLowerCase();if(s.includes('external action')||s.includes('external_gate'))return'Not connected — setup required';if(s.includes('connected')&&!s.includes('not'))return'Connected';return status;}
;

/* --- ./app-10.js --- */
function renderField(){const jobs=records('jobs'),notes=records('jobNotes'),times=records('timeEntries');$('mainContent').innerHTML=pageHead('Site Visits','Capture job notes, photos, time and closeout evidence with poor or no service.',`<button id="fieldVoiceButton" class="secondary">Voice commands</button>`)+`<div class="grid"><div id="h38FieldVoiceMount" class="span12"></div><section class="card span5"><h2>Field capture</h2><form id="jobNoteForm"><label>Job</label><select name="jobId" required>${optionRows(jobs,['Job ID'],row=>`${v(row,'Job Number')} — ${v(row,'Project Title')}`,'Select job')}</select><label>Note type</label><select name="noteType"><option>Progress</option><option>Issue</option><option>Measurement</option><option>Customer Request</option><option>Closeout</option></select><label>Note</label><textarea name="body" required></textarea><div class="actions"><button>Save job note</button><button type="button" class="secondary" id="fieldPhotoButton">📷 Take photo</button><input id="fieldPhotoInput" type="file" accept="image/*" capture="environment" class="hidden"></div></form></section><section class="card span4"><h2>Time entry</h2><form id="timeForm"><label>Job</label><select name="jobId">${optionRows(jobs,['Job ID'],row=>v(row,'Project Title'),'Select job')}</select><div class="two"><div><label>Start</label><input name="startTime" type="datetime-local"></div><div><label>End</label><input name="endTime" type="datetime-local"></div></div><label>Break minutes</label><input name="breakMinutes" type="number" value="0"><label>Notes</label><input name="notes"><div class="actions"><button>Record time</button></div></form></section><section class="card span3"><h2>Driving mode</h2><div id="h38DrivingVoiceMount"></div><label class="notice"><input id="drivingModeToggle" type="checkbox" ${state.drivingMode?'checked':''}> Read work and queue drafts without complex screen actions.</label><p class="muted small">Pricing, sending, approvals, payments, deletion and settings changes always wait for parked review.</p></section><section class="card span7"><h2>Recent job notes</h2><div class="list">${notes.length?notes.slice(0,50).map(row=>`<div class="row"><div class="row-top"><strong>${esc(jobName(v(row,'Job ID')))}</strong>${pill(v(row,'Note Type'))}</div><small>${esc(v(row,'Body'))} · ${dateTime(v(row,'Created Time'))}</small></div>`).join(''):empty('No field notes.')}</div></section><section class="card span5"><h2>Recent time</h2><div class="list">${times.length?times.slice(0,30).map(row=>`<div class="row"><strong>${esc(jobName(v(row,'Job ID')))}</strong><small>${esc(v(row,'Hours'))} hours · ${dateTime(v(row,'Start Time'))}</small></div>`).join(''):empty('No time entries.')}</div></section></div>`;$('fieldVoiceButton').onclick=function(){if(window.H38VoiceCommands)window.H38VoiceCommands.toggle();else toggleVoice();};$('fieldPhotoButton').onclick=()=>$('fieldPhotoInput').click();$('fieldPhotoInput').onchange=event=>{const jobId=$('jobNoteForm').elements.jobId.value;if(!jobId)return toast('Select a job before taking the photo.',true);handleAttachmentFiles(event.target.files,'Job',jobId);};$('drivingModeToggle').onchange=async event=>{state.drivingMode=event.target.checked;const settings=await get('meta','settings')||{id:'settings',bridgeUrl:BRIDGE_URL};settings.drivingMode=state.drivingMode;await put('meta',settings);try{const dm=document.getElementById('h38DrivingVoiceMount');if(dm&&window.H38VoiceCommands){dm.innerHTML=window.H38VoiceCommands.drivingVoiceNudge();window.H38VoiceCommands.bindDrivingVoice();}}catch(e){}toast(`Driving mode ${state.drivingMode?'enabled':'disabled'}.`);};bindForm('jobNoteForm',async(data,form)=>{const id=newId('JOB-NOTE'),record={'Job Note ID':id,'Business ID':state.businessId,'Job ID':data.jobId,'Note Type':data.noteType,'Body':requireValue(data.body,'Note is required.'),'Visibility':'Internal','Created By':state.snapshot.user.userId,'Created Time':now(),'Record Version':1};await queueOperation('SAVE_ENTITY','Job Note',id,{entity:'jobNotes',record},{collection:'jobNotes',record,idKeys:['Job Note ID']});form.elements.body.value='';toast('Field note saved offline.');renderField();});(function(){try{var mount=document.getElementById('h38FieldVoiceMount');if(mount&&window.H38VoiceCommands&&window.H38VoiceCommands.ensureBar){var bar=window.H38VoiceCommands.ensureBar();if(bar&&bar.parentNode!==mount){if(bar.parentNode)bar.parentNode.removeChild(bar);mount.appendChild(bar);}}var dm=document.getElementById('h38DrivingVoiceMount');if(dm&&window.H38VoiceCommands){dm.innerHTML=window.H38VoiceCommands.drivingVoiceNudge();window.H38VoiceCommands.bindDrivingVoice();}}catch(e){}} )();bindForm('timeForm',async(data,form)=>{const id=newId('TIME'),hours=data.startTime&&data.endTime?Math.max(0,(new Date(data.endTime)-new Date(data.startTime))/3600000-num(data.breakMinutes)/60):0,record={'Time Entry ID':id,'Business ID':state.businessId,'User ID':state.snapshot.user.userId,'Job ID':data.jobId,'Start Time':data.startTime,'End Time':data.endTime,'Break Minutes':num(data.breakMinutes),'Hours':Math.round(hours*100)/100,'Status':'Recorded','Notes':data.notes,'Created Time':now(),'Updated Time':now(),'Record Version':1};await queueOperation('RECORD_TIME','Time Entry',id,{timeEntryId:id,timeSource:'field_form',...data},{collection:'timeEntries',record,idKeys:['Time Entry ID']});form.reset();toast('Time entry queued.');renderField();});}
;

/* --- ./app-11.js --- */
function renderInventory(){if(!(window.H38OwnerControls&&window.H38OwnerControls.isInventoryEnabled&&window.H38OwnerControls.isInventoryEnabled())){$('mainContent').innerHTML=pageHead('Inventory','Inventory & Materials is off for this business.')+'<section class="card"><h2>Inventory is turned off</h2><p class="muted">Turn on <strong>Inventory &amp; Materials</strong> in Owner Controls (Settings) to track stock, reorder points, rentals and advertised availability. Your price book keeps working in Quote Builder either way.</p></section>';return;}const items=records('priceBook'),transactions=records('inventoryTransactions'),jobs=records('jobs'),requests=records('materialRequests');const stock=new Map();transactions.forEach(row=>{const id=v(row,'Item ID'),qty=Math.abs(num(v(row,'Quantity'))),dir=String(v(row,'Direction')).toUpperCase();stock.set(id,(stock.get(id)||0)+(dir==='OUT'?-qty:qty));});$('mainContent').innerHTML=pageHead('Inventory','Receive, issue, reserve and request materials using append-only transactions.')+`<div class="grid"><section class="card span5"><h2>Receive or issue stock</h2><form id="inventoryForm"><label>Item</label><select name="itemId" required>${optionRows(items,['Item ID'],row=>`${v(row,'SKU')} — ${v(row,'Description')}`,'Select item')}</select><div class="three"><div><label>Direction</label><select name="direction"><option value="IN">Receive</option><option value="OUT">Issue</option></select></div><div><label>Quantity</label><input name="quantity" type="number" step="0.01" required></div><div><label>Unit cost</label><input name="unitCost" type="number" step="0.01"></div></div><label>Job</label><select name="jobId">${optionRows(jobs,['Job ID'],row=>v(row,'Project Title'),'No job')}</select><label>Reason</label><input name="reason"><div class="actions"><button>Record transaction</button></div></form></section>${(typeof lowStockCard==='function'&&window.H38OwnerControls&&window.H38OwnerControls.isEnabled('inventory_low_stock'))?lowStockCard():''}${window.H38InventoryModule?window.H38InventoryModule.editorCard():''}<section class="card span7"><h2>Stock</h2><div class="list">${items.length?items.slice(0,150).map(row=>{const onHand=stock.get(v(row,'Item ID'))||0,reorder=num(v(row,'Reorder Point'));return`<div class="row"><div class="row-top"><strong>${esc(v(row,'Description'))}</strong>${pill(`${onHand} ${v(row,'Unit of Measure')||''}`,reorder&&onHand<=reorder?'bad':'good')}</div><small>${esc(v(row,'SKU'))} · cost ${money(v(row,'Purchase Cost'))} · sell ${money(v(row,'Selling Price'))}${v(row,'Rentable')?` · rents ${money(v(row,'Rental Rate'))}`:''}${v(row,'Advertise')?' · 📣 advertised':''}${v(row,'Sellable')===false?' · not sellable':''}</small></div>`;}).join(''):empty('No inventory items.')}</div></section>${window.H38InventoryModule?window.H38InventoryModule.advertisedCard():''}${(typeof priceHistoryCard==='function'&&window.H38OwnerControls&&window.H38OwnerControls.isEnabled('price_history'))?priceHistoryCard():''}<section class="card"><h2>Material requests</h2><form id="materialRequestForm" class="four"><div><label>Job</label><select name="jobId">${optionRows(jobs,['Job ID'],row=>v(row,'Project Title'),'Select job')}</select></div><div><label>Needed date</label><input name="neededDate" type="date"></div><div><label>Priority</label><select name="priority"><option>Normal</option><option>High</option><option>Urgent</option></select></div><div><label>Items / notes</label><input name="notes"></div><div class="actions"><button>Request materials</button></div></form><div class="list">${requests.length?requests.map(row=>`<div class="row"><div class="row-top"><strong>${esc(jobName(v(row,'Job ID')))}</strong>${pill(v(row,'Status'))}</div><small>${esc(v(row,'Notes'))} · needed ${dateOnly(v(row,'Needed Date'))}</small></div>`).join(''):empty('No material requests.')}</div></section></div>`;bindForm('inventoryForm',async(data,form)=>{const id=newId('TXN'),record={'Transaction ID':id,'Business ID':state.businessId,'Item ID':data.itemId,'Quantity':num(data.quantity),'Direction':data.direction,'Unit Cost':num(data.unitCost),'Job ID':data.jobId,'Reason':data.reason,'Timestamp':now(),'Record Version':1};await queueOperation('POST_INVENTORY','Inventory Transaction',id,{...data,operationId:id},{collection:'inventoryTransactions',record,idKeys:['Transaction ID']});form.reset();toast('Append-only inventory transaction queued.');renderInventory();});bindForm('materialRequestForm',async(data,form)=>{const id=newId('MATERIAL-REQUEST'),record={'Material Request ID':id,'Business ID':state.businessId,'Job ID':data.jobId,'Requested By':state.snapshot.user.userId,'Needed Date':data.neededDate,'Priority':data.priority,'Items JSON':'[]','Status':'Open','Notes':data.notes,'Created Time':now(),'Updated Time':now(),'Record Version':1};await queueOperation('SAVE_ENTITY','Material Request',id,{entity:'materialRequests',record},{collection:'materialRequests',record,idKeys:['Material Request ID']});form.reset();toast('Material request queued.');renderInventory();});}
;

/* --- ./app-12.js --- */
function renderFleet(){const assets=records('assets'),jobs=records('jobs'),maintenance=records('maintenance'),inspections=records('inspections');$('mainContent').innerHTML=pageHead('Fleet & Equipment','Track vehicles, trailers, tools, job assignments, usage, inspections, downtime and maintenance.')+`<div class="grid"><section class="card span4"><h2>Assign or return equipment</h2><form id="assetAssignmentForm"><label>Equipment</label><select name="assetId" required>${optionRows(assets,['Asset ID'],row=>`${v(row,'Asset Number')} — ${v(row,'Description')}`,'Select equipment')}</select><label>Job</label><select name="jobId">${optionRows(jobs,['Job ID'],row=>`${v(row,'Job Number')} — ${v(row,'Project Title')}`,'Select job')}</select><label>Condition</label><input name="condition" placeholder="Good, damaged guard…"><div class="actions"><button name="mode" value="assign">Assign</button><button name="mode" value="return" class="secondary">Return</button></div></form></section><section class="card span4"><h2>Inspection</h2><form id="inspectionForm"><label>Equipment</label><select name="assetId" required>${optionRows(assets,['Asset ID'],row=>v(row,'Description'),'Select equipment')}</select><div class="two"><div><label>Type</label><select name="inspectionType"><option>Pre-use</option><option>Routine</option><option>Annual</option><option>Return</option></select></div><div><label>Result</label><select name="result"><option>PASS</option><option>FAIL</option></select></div></div><label>Notes</label><textarea name="notes"></textarea><div class="actions"><button>Record inspection</button></div></form></section><section class="card span4"><h2>Maintenance</h2><form id="maintenanceForm"><label>Equipment</label><select name="assetId" required>${optionRows(assets,['Asset ID'],row=>v(row,'Description'),'Select equipment')}</select><label>Service type</label><input name="maintenanceType" value="Service"><div class="two"><div><label>Due date</label><input name="dueDate" type="date"></div><div><label>Priority</label><select name="priority"><option>Normal</option><option>High</option><option>Urgent</option></select></div></div><label>Notes</label><textarea name="notes"></textarea><div class="actions"><button>Schedule maintenance</button></div></form></section><section class="card span8"><h2>Fleet and equipment</h2><div class="list">${assets.length?assets.slice(0,150).map(row=>`<div class="row"><div class="row-top"><strong>${esc(v(row,'Description'))}</strong>${pill(v(row,'Availability')||v(row,'Status'),dueSoon(v(row,'Next Service'))?'bad':'')}</div><small>${esc(v(row,'Asset Number'))} · ${esc(v(row,'Asset Type')||v(row,'Category'))}${v(row,'Assigned Job ID')?' · '+esc(jobName(v(row,'Assigned Job ID'))):''}${v(row,'Next Service')?' · service '+dateOnly(v(row,'Next Service')):''}</small></div>`).join(''):empty('No fleet or equipment.')}</div></section><section class="card span4"><h2>Open maintenance</h2><div class="list">${maintenance.length?maintenance.filter(row=>String(v(row,'Status')).toUpperCase()!=='COMPLETE').slice(0,40).map(row=>`<div class="row"><div class="row-top"><strong>${esc(assetName(v(row,'Asset ID')))}</strong>${pill(v(row,'Priority'))}</div><small>${esc(v(row,'Maintenance Type'))} · ${dateOnly(v(row,'Due Date'))} · ${esc(v(row,'Status'))}</small></div>`).join(''):empty('No open maintenance.')}</div><h3>Recent inspections</h3><div class="list">${inspections.slice(0,20).map(row=>`<div class="row"><strong>${esc(assetName(v(row,'Asset ID')))}</strong><small>${esc(v(row,'Inspection Type'))} · ${esc(v(row,'Result'))}</small></div>`).join('')}</div></section></div>`;const assignmentForm=$('assetAssignmentForm');assignmentForm.onsubmit=async event=>{event.preventDefault();const data=formObject(assignmentForm),mode=event.submitter.value;if(mode==='assign'){requireValue(data.jobId,'Select a job to assign equipment.');await queueOperation('ASSIGN_ASSET','Asset',data.assetId,{assetId:data.assetId,jobId:data.jobId,conditionOut:data.condition});}else await queueOperation('RETURN_ASSET','Asset',data.assetId,{assetId:data.assetId,conditionIn:data.condition});toast(`Equipment ${mode==='assign'?'assignment':'return'} queued.`);};bindForm('inspectionForm',async(data,form)=>{const id=newId('INSPECTION'),record={'Inspection ID':id,'Business ID':state.businessId,'Asset ID':data.assetId,'Inspection Type':data.inspectionType,'Result':data.result,'Notes':data.notes,'Inspection Time':now(),'Record Version':1};await queueOperation('RECORD_INSPECTION','Inspection',id,{inspectionId:id,...data},{collection:'inspections',record,idKeys:['Inspection ID']});form.reset();toast('Inspection queued.');renderFleet();});bindForm('maintenanceForm',async(data,form)=>{const id=newId('MAINTENANCE'),record={'Maintenance ID':id,'Business ID':state.businessId,'Asset ID':data.assetId,'Maintenance Type':data.maintenanceType,'Status':'Scheduled','Priority':data.priority,'Due Date':data.dueDate,'Notes':data.notes,'Created Time':now(),'Updated Time':now(),'Record Version':1};await queueOperation('SCHEDULE_MAINTENANCE','Maintenance',id,{maintenanceId:id,...data},{collection:'maintenance',record,idKeys:['Maintenance ID']});form.reset();toast('Maintenance scheduled.');renderFleet();});}
;

/* --- ./app-13.js --- */
function invoiceRemoved(row){const status=String(v(row,'Status')||'').toUpperCase();return /DELET|VOID/.test(status)||v(row,'Deleted')===true||String(v(row,'Deleted')||'').toLowerCase()==='true';}
async function deleteInvoice(invoiceId){const invoice=records('invoices').find(row=>String(v(row,'Invoice ID'))===String(invoiceId));if(!invoice){toast('Invoice could not be found.',true);return;}const relatedPayments=records('payments').filter(row=>String(v(row,'Invoice ID'))===String(invoiceId));if(relatedPayments.length){toast('This invoice has payment history and cannot be deleted. Keep the audit record and use an adjustment instead.',true);return;}const number=v(invoice,'Invoice Number')||invoiceId;if(!confirm(`Delete invoice ${number}? It will be removed from active invoices but retained in audit history.`))return;const updated={...invoice,'Status':'Deleted','Deleted':true,'Deleted Time':now(),'Deletion Mode':'Soft delete — audit retained','Send Allowed':'No','Balance':0,'Balance Due':0,'Amount Due':0,'Open Balance':0,'Updated Time':now(),'Record Version':Math.max(1,num(v(invoice,'Record Version'))+1)};delete updated.__localPending;await queueOperation('SAVE_ENTITY','Invoice',invoiceId,{entity:'invoices',record:updated},{collection:'invoices',record:updated,idKeys:['Invoice ID']},true);toast('Invoice deleted from active records. Audit history retained.');renderMoney();}

/* ---- Invoice send (Phase 3, Pattern 4: draft → sent is a button) ----
   Manual "mark as sent" is the honest path: it records that the owner sent
   the invoice through their own channel. Nothing is emailed automatically.
   Delivery Status + timestamp + status history all update (Pattern 4). */
async function markInvoiceSent(invoiceId){
  const invoice=records('invoices').find(row=>String(v(row,'Invoice ID'))===String(invoiceId));
  if(!invoice){toast('Invoice could not be found.',true);return;}
  const number=v(invoice,'Invoice Number')||invoiceId;
  const status=String(v(invoice,'Status')||'');
  if(/^(sent|paid|partially paid)$/i.test(status)){toast('Invoice '+number+' is already marked as sent.',true);return;}
  const flow=window.H38Flow;
  const confirmed=flow&&flow.confirm
    ?await flow.confirm({title:'Mark as sent',message:'Mark invoice '+number+' as sent to the customer? This records that you sent it. Nothing is emailed automatically.',okLabel:'Mark as sent'})
    :confirm('Mark invoice '+number+' as sent to the customer?');
  if(!confirmed)return;
  try{
    const appr=v(invoice,'Approval Status');
    const updated={...invoice,'Status':'Sent','Delivery Status':'Sent','Sent Time':now(),'Approval Status':/approval required/i.test(String(appr||''))?'Approved — Owner Recorded':appr,'Status History':flow?flow.pushStatusHistory(invoice,status||'Draft','Sent'):(v(invoice,'Status History')||''),'Updated Time':now(),'Record Version':Math.max(1,num(v(invoice,'Record Version'))+1)};
    delete updated.__localPending;
    await queueOperation('SAVE_ENTITY','Invoice',invoiceId,{entity:'invoices',record:updated},{collection:'invoices',record:updated,idKeys:['Invoice ID']},true);
    toast('Invoice '+number+' marked as sent. Next: record payment when paid.');
    renderMoney();
  }catch(error){toast(error?.message||String(error),true);}
}
/* Scroll the invoices list to one invoice row and flash it. */
function h38ScrollToInvoice(invoiceId){
  const el=document.querySelector('[data-invoice-row="'+CSS.escape(String(invoiceId||''))+'"]');
  if(!el){window.toast?.('That invoice is not visible in the list below.',true);return;}
  el.scrollIntoView({behavior:'smooth',block:'center'});
  el.classList.add('h38-flash');
  setTimeout(()=>el.classList.remove('h38-flash'),1800);
}
/* From the invoice post-save panel: jump to the payment form with the new
 * invoice preselected so recording payment is one tap away (Pattern 2). */
function h38FocusPaymentFor(invoiceId){
  const form=document.getElementById('paymentForm');
  const sel=form?form.querySelector('[name="invoiceId"]'):null;
  let preselected=false;
  if(sel){const opt=Array.from(sel.options||[]).find(o=>String(o.value)===String(invoiceId));if(opt){sel.value=opt.value;preselected=true;}}
  if(form){form.scrollIntoView({behavior:'smooth',block:'center'});form.querySelector('[name="amount"]')?.focus({preventScroll:true});}
  if(!preselected)window.toast?.('This invoice has no open balance, so it cannot be selected for payment.',true);
}

