function attachmentCustomerId(relatedRecordType,relatedRecordId,metadata={}){const explicit=String(metadata.customerId||'').trim();if(explicit)return explicit;const type=String(relatedRecordType||'').trim().toLowerCase(),id=String(relatedRecordId||'').trim();if(type==='customer')return id;const map={job:['jobs',['Job ID','jobId']],quote:['quotes',['Quote ID','quoteId']],request:['requests',['Request ID','requestId']],invoice:['invoices',['Invoice ID','invoiceId']],property:['properties',['Property ID','propertyId']],'site capture':['siteCaptureSessions',['Site Visit ID','visitId','Session ID','sessionId']]},spec=map[type];if(!spec||!id)return'';const row=records(spec[0]).find(item=>spec[1].some(key=>String(item?.[key]||'')===id));return String(v(row,'Customer ID','customerId')||'').trim();}
async function handleAttachmentFiles(fileList,relatedRecordType,relatedRecordId,visibility='Internal',metadata={}){for(const file of Array.from(fileList||[])){try{const customerId=attachmentCustomerId(relatedRecordType,relatedRecordId,metadata);if(!file.type.startsWith('image/')&&file.size>3000000){const largeUploader=window.H38_CUSTOMER_WORKSPACE_DOCUMENTS?.uploadLargeFile;if(typeof largeUploader!=='function')throw new Error('Files over 3 MB need the secure online document uploader.');await largeUploader(file,relatedRecordType,relatedRecordId,visibility,{...metadata,customerId});continue;}const prepared=await prepareFile(file),id=newId('ATTACHMENT'),record={id,attachmentId:id,businessId:state.businessId,customerId,fileName:prepared.fileName,mimeType:prepared.mimeType,fileSize:prepared.fileSize,base64Data:prepared.base64Data,relatedRecordType,relatedRecordId,visibility,captureTime:now(),syncStatus:'PENDING'};await put('attachments',record);await queueOperation('SAVE_ATTACHMENT','Attachment',id,record);toast(`${file.name} saved on this device.`);}catch(error){toast(`${file.name}: ${error.message}`,true);}}renderAttachmentQueue();await updatePending();}
async function prepareFile(file){if(file.type.startsWith('image/'))return resizeImage(file);if(file.size>3000000)throw new Error('File is over the offline 3 MB limit. Connect to upload it securely.');return{fileName:file.name,mimeType:file.type||'application/octet-stream',fileSize:file.size,base64Data:await fileBase64(file)};}
function fileBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file);});}
function resizeImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(reader.error);reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error('Image could not be read.'));image.onload=()=>{const max=1600,scale=Math.min(1,max/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);let quality=.82,data=canvas.toDataURL('image/jpeg',quality);while(data.length>3600000&&quality>.45){quality-=.08;data=canvas.toDataURL('image/jpeg',quality);}const base64=data.split(',')[1],size=Math.round(base64.length*.75);if(size>3000000)return reject(new Error('Photo is still over 3 MB after reduction.'));resolve({fileName:file.name.replace(/\.[^.]+$/,'.jpg'),mimeType:'image/jpeg',fileSize:size,base64Data:base64});};image.src=reader.result;};reader.readAsDataURL(file);});}
async function renderAttachmentQueue(){const rows=(await all('attachments')).filter(row=>row.businessId===state.businessId);const node=$('attachmentQueue');if(node)node.innerHTML=rows.length?rows.map(row=>`<div class="row"><div class="row-top"><strong>${esc(row.fileName)}</strong>${pill(row.syncStatus,'pending')}</div><small>${esc(row.relatedRecordType)} ${esc(row.relatedRecordId)} · ${Math.round(row.fileSize/1024)} KB</small></div>`).join(''):empty('No files waiting on this device.');}
;

