function renderSocial(){const posts=records('socialPosts'),campaigns=records('campaigns'),accounts=records('socialAccounts'),metrics=records('socialMetrics');$('mainContent').innerHTML=pageHead('Social Control','Draft, review, approve, schedule, record manual posting proof and track results without uncontrolled publishing.')+`<div class="grid"><section class="card span6"><h2>Create social content</h2><form id="socialPostForm"><div class="two"><div><label>Platform</label><select name="platform"><option>Facebook</option><option>Instagram</option><option>LinkedIn</option><option>Google Business Profile</option><option>YouTube</option><option>General</option></select></div><div><label>Campaign</label><select name="campaignId">${optionRows(campaigns,['Campaign ID'],row=>v(row,'Campaign Name'),'No campaign')}</select></div></div><label>Title / hook</label><input name="title"><label>Post copy</label><textarea name="body" required></textarea><label>Link</label><input name="linkUrl" type="url" value="${esc(H38_PUBLIC_SITE_URL)}"><p class="muted small">Highway 38 links use highway38solutions.com. Old website links are corrected when the draft is saved.</p><label>Internal schedule</label><input name="scheduledTime" type="datetime-local"><div class="actions"><button>Save draft</button></div></form><div class="notice warn">Automatic publishing is disabled. Owner-approved posts can be scheduled internally, manually posted and verified with proof.</div></section><section class="card span3"><h2>Campaign</h2><form id="campaignForm"><label>Name</label><input name="campaignName" required><label>Goal</label><input name="goal"><div class="two"><div><label>Start</label><input name="startDate" type="date"></div><div><label>End</label><input name="endDate" type="date"></div></div><div class="actions"><button>Save campaign</button></div></form></section><section class="card span3"><h2>Connections</h2><div class="list">${accounts.length?accounts.map(row=>`<div class="row provider"><strong>${esc(v(row,'Platform'))}</strong>${pill(v(row,'Connection Status'))}</div>`).join(''):empty(`Social provider: ${providerStatus('social')}`)}</div><p class="muted small">Provider connections will be business-specific. No H38 credential or account is copied into another business.</p></section><section class="card span8"><h2>Content calendar and review</h2><div class="list">${posts.length?posts.slice(0,120).map(socialPostRow).join(''):empty('No social drafts.')}</div></section><section class="card span4"><h2>Performance</h2><div class="stats"><div class="stat"><strong>${metrics.reduce((sum,row)=>sum+num(v(row,'Reach')),0)}</strong><span>Reach</span></div><div class="stat"><strong>${metrics.reduce((sum,row)=>sum+num(v(row,'Engagements')),0)}</strong><span>Engagements</span></div><div class="stat"><strong>${metrics.reduce((sum,row)=>sum+num(v(row,'Leads')),0)}</strong><span>Leads</span></div><div class="stat"><strong>${money(metrics.reduce((sum,row)=>sum+num(v(row,'Revenue')),0))}</strong><span>Attributed revenue</span></div></div><form id="metricForm"><label>Post</label><select name="socialPostId">${optionRows(posts,['Social Post ID'],row=>`${v(row,'Platform')} — ${v(row,'Title')||String(v(row,'Body')).slice(0,35)}`,'Select post')}</select><div class="two"><div><label>Reach</label><input name="reach" type="number"></div><div><label>Engagements</label><input name="engagements" type="number"></div></div><div class="two"><div><label>Leads</label><input name="leads" type="number"></div><div><label>Revenue</label><input name="revenue" type="number" step="0.01"></div></div><div class="actions"><button>Record metrics</button></div></form></section></div>`;bindForm('socialPostForm',async(data,form)=>{const id=newId('SOCIAL-POST'),linkUrl=normalizeSocialLinkUrl(data.linkUrl),normalizedData={...data,linkUrl},record={'Social Post ID':id,'Business ID':state.businessId,'Campaign ID':data.campaignId,'Platform':data.platform,'Title':data.title,'Body':requireValue(data.body,'Post copy is required.'),'Link URL':linkUrl,'Status':data.scheduledTime?'Draft Scheduled — Approval Required':'Draft','Scheduled Time':data.scheduledTime,'Created By':state.snapshot.user.userId,'Created Time':now(),'Updated Time':now(),'Record Version':1};await queueOperation('SAVE_SOCIAL_POST','Social Post',id,{socialPostId:id,...normalizedData},{collection:'socialPosts',record,idKeys:['Social Post ID']});form.reset();toast('Social draft saved with the public Highway 38 URL. Nothing published.');renderSocial();});bindForm('campaignForm',async(data,form)=>{const id=newId('CAMPAIGN'),record={'Campaign ID':id,'Business ID':state.businessId,'Campaign Name':requireValue(data.campaignName,'Campaign name is required.'),'Campaign Type':'Organic','Start Date':data.startDate,'End Date':data.endDate,'Status':'Active','Goal':data.goal,'Created Time':now(),'Updated Time':now(),'Record Version':1};await queueOperation('SAVE_CAMPAIGN','Campaign',id,{campaignId:id,...data},{collection:'campaigns',record,idKeys:['Campaign ID']});form.reset();toast('Campaign saved.');renderSocial();});bindForm('metricForm',async(data,form)=>{await queueOperation('RECORD_SOCIAL_METRIC','Social Metric',newId('SOCIAL-METRIC'),{...data,platform:'Manual',metricDate:new Date().toISOString().slice(0,10),source:'Manual'});form.reset();toast('Social metrics queued.');});document.querySelectorAll('[data-social-review]').forEach(button=>button.onclick=()=>socialAction('REQUEST_SOCIAL_REVIEW',button.dataset.socialReview,{socialPostId:button.dataset.socialReview}));document.querySelectorAll('[data-social-approve]').forEach(button=>button.onclick=()=>socialAction('APPROVE_SOCIAL_POST',button.dataset.socialApprove,{socialPostId:button.dataset.socialApprove,decision:'APPROVE'}));document.querySelectorAll('[data-social-posted]').forEach(button=>button.onclick=()=>manualPosted(button.dataset.socialPosted));}
function socialPostRow(row){const id=rowId(row,'Social Post ID'),linkUrl=normalizeSocialLinkUrl(v(row,'Link URL'));return`<div class="row"><div class="row-top"><strong>${esc(v(row,'Platform'))}: ${esc(v(row,'Title')||String(v(row,'Body')).slice(0,60))}</strong>${pill(v(row,'Status'),String(v(row,'Status')).includes('Published')?'good':String(v(row,'Status')).includes('Approval')?'pending':'')}</div><div class="social-preview">${esc(v(row,'Body'))}</div>${linkUrl?`<small>Link: ${esc(linkUrl)}</small>`:''}<small>${v(row,'Scheduled Time')?'Scheduled '+dateTime(v(row,'Scheduled Time')):'Not scheduled'} · ${v(row,'Approved By')?'approved by '+esc(userName(v(row,'Approved By'))):'approval required'}</small><div class="row-actions"><button data-social-review="${esc(id)}">Request review</button><button data-social-approve="${esc(id)}">Owner approve</button><button data-social-posted="${esc(id)}">Record manual post</button></div></div>`;}
async function socialAction(action,id,payload){await queueOperation(action,'Social Post',id,payload);toast('Social action queued. No automatic publication occurred.');}
async function manualPosted(id){const proof=prompt('Enter the public post URL or provider post ID.');if(!proof)return;await queueOperation('MARK_SOCIAL_POSTED','Social Post',id,{socialPostId:id,publicUrl:proof,publishedTime:now()});toast('Manual publication proof queued.');}

// Live-first PWA compatibility bootstrap: existing installed Offices can load the new Customer 360 timeline even if an older customer workspace hook is still cached.
(function(){
  const BUILD='20260920-canonical-workspace-2';
  let loading=false;
  function ensureCustomer360Timeline(){
    if(String(window.state?.page||'')!=='customers')return;
    if(window.H38_CUSTOMER_360_TIMELINE){window.H38_CUSTOMER_360_TIMELINE.reconcile?.();return;}
    if(loading)return;
    let script=document.querySelector('script[data-h38-customer-360-timeline]');
    if(script)return;
    loading=true;script=document.createElement('script');script.src=`./customer-360-timeline.js?build=${BUILD}`;script.async=false;script.dataset.h38Customer360Timeline='1';
    script.addEventListener('load',()=>{loading=false;window.H38_CUSTOMER_360_TIMELINE?.reconcile?.();},{once:true});
    script.addEventListener('error',()=>{loading=false;console.warn('[H38 Customer 360 timeline bootstrap] Timeline could not load.');},{once:true});
    document.body.appendChild(script);
  }
  window.addEventListener?.('h38:office-page-rendered',ensureCustomer360Timeline);
  window.addEventListener?.('h38:business-snapshot-updated',ensureCustomer360Timeline);
  window.addEventListener?.('pageshow',ensureCustomer360Timeline);
  queueMicrotask(ensureCustomer360Timeline);
})();
;

/* --- ./app-16.js --- */
/* H38 AI page — rebuilt 2026-10-11 as "Kit's Workspace" (dashboard, not chatbot).
 * renderAi() delegates to window.H38KitsWorkspace (kits-workspace.js).
 * The Ask Kit chat lives at the bottom of the workspace; askAi/toggleVoice
 * handlers below are kept and wired by the workspace module. */
function renderAi(){
  if (window.H38KitsWorkspace && typeof window.H38KitsWorkspace.render === 'function') {
    window.H38KitsWorkspace.render();
    return;
  }
  /* Fallback if the workspace module failed to load: simple chat. */
  const chat = (window.state && window.state.aiChat) || [];
  document.getElementById('mainContent').innerHTML =
    '<div class="kw-workspace"><section class="card kw-chat"><h2>Ask Hank</h2>' +
    '<div id="kwAiChat" class="ai-chat">' +
    (chat.length ? chat.map(function (m) {
      return '<div class="ai-bubble ' + esc(m.role) + '">' + esc(m.body) + '</div>';
    }).join('') : '<div class="ai-bubble assistant">Ask Hank anything about your business.</div>') +
    '</div><form id="kwAiForm"><label>Question</label>' +
    '<textarea name="question" required placeholder="What should I work on next?"></textarea>' +
    '<div class="actions"><button>Ask Hank</button></div></form></section></div>';
  var form = document.getElementById('kwAiForm');
  if (form) bindForm(form, askAi);
}
async function askAi(data,form){const question=requireValue(data.question,'Ask a question first.');state.aiChat.push({role:'user',body:question});form.reset();renderAi();let answer;if(navigator.onLine&&state.bridgeReady){try{const result=await state.bridge.request('aiAsk',{businessId:state.businessId,question,pageKey:state.page,aiConversationId:state.aiConversationId});state.aiConversationId=result.aiConversationId;answer=result.answer;}catch(error){answer=localAi(question);}}else answer=localAi(question);state.aiChat.push({role:'assistant',body:answer});renderAi();speak(answer);}
function localAi(question){const q=question.toLowerCase(),knowledge=records('aiKnowledge'),tokens=q.split(/\W+/).filter(token=>token.length>2),ranked=knowledge.map(row=>({row,score:tokens.reduce((sum,token)=>sum+(`${v(row,'Topic')} ${v(row,'Title')} ${v(row,'Content')}`.toLowerCase().includes(token)?1:0),0)})).sort((a,b)=>b.score-a.score);return ranked[0]?.score?ranked.slice(0,3).map(item=>`${v(item.row,'Title')}: ${v(item.row,'Content')}`).join('\n\n'):'I can still capture work offline. Product-specific cloud AI and provider actions require a connection.';}

function aiContext(){
  const pageLabel=PAGE_DEFS[state.page]?.[1]||'Business Office',context={shell:state.shell,pageKey:state.page,pageLabel,businessId:state.businessId};
  if(state.page==='quotes'){context.quoteId=state.quote?.quoteId||'';context.projectTitle=state.quote?.projectTitle||'';context.scope=state.quote?.scope||'';context.measurementNotes=state.quote?.measurementNotes||'';}
  if(state.selectedConversation)context.conversationId=state.selectedConversation;
  return context;
}
function aiContextLabel(){const context=aiContext();if(context.pageKey==='quotes')return context.projectTitle?`Quote Builder · ${context.projectTitle}`:'Quote Builder · new draft';return context.pageLabel;}
function openGlobalAi(){
  const dialog=$('globalAiDialog');if(!dialog)return;renderGlobalAi();if(!dialog.open)dialog.showModal();
}
function renderGlobalAi(){
  const body=$('globalAiBody');if(!body)return;
  const canOpenFull=allowedPages().includes('ai');
  body.innerHTML=`<div class="ai-drawer-shell"><header class="ai-drawer-head"><div><strong>✨ Hank</strong><small>Working with: ${esc(aiContextLabel())}</small></div><button id="closeGlobalAiButton" class="ai-drawer-close" type="button" aria-label="Close Hank">×</button></header><div class="ai-drawer-content">${state.snapshot?`<div class="ai-context">Hank keeps the current page, business and quote context while you ask.</div><div id="globalAiChat" class="ai-chat">${state.aiChat.length?state.aiChat.map(message=>`<div class="ai-bubble ${message.role}">${esc(message.body)}</div>`).join(''):`<div class="ai-bubble assistant">I am ready on ${esc(aiContextLabel())}. Ask what to do next, how to use this screen, or for help with the current quote.</div>`}</div><form id="globalAiForm"><label>Ask Hank</label><textarea name="question" required placeholder="What should I do next on this screen?"></textarea><div class="actions"><button>Ask Hank</button>${canOpenFull?'<button id="openFullAiButton" type="button" class="secondary">Open full Hank chat</button>':''}</div></form>`:'<div class="notice">Open the secure Business Office first, then Hank will use the active page and business context.</div>'}</div></div>`;
  $('closeGlobalAiButton').onclick=()=>$('globalAiDialog').close();
  if(state.snapshot){bindForm('globalAiForm',askGlobalAi);if(canOpenFull)$('openFullAiButton').onclick=()=>{$('globalAiDialog').close();openPage('ai');};}
}
async function askGlobalAi(data,form){
  const question=requireValue(data.question,'Ask a question first.'),context=aiContext();state.aiChat.push({role:'user',body:question});form.reset();renderGlobalAi();
  let answer;
  if(navigator.onLine&&state.bridgeReady){try{const result=await state.bridge.request('aiAsk',{businessId:state.businessId,question,pageKey:state.page,context,aiConversationId:state.aiConversationId});state.aiConversationId=result.aiConversationId;answer=result.answer;}catch(error){answer=localAi(question);}}
  else answer=localAi(question);
  state.aiChat.push({role:'assistant',body:answer});renderGlobalAi();
  const chat=$('globalAiChat');if(chat)chat.scrollTop=chat.scrollHeight;
}
;

/* --- ./app-17.js --- */
function friendlyModuleName(slug){const names={'accounting':'Accounting','ai':'Hank','approvals':'Approvals','checklists':'Checklists','communications':'Communications','controls':'Owner Controls','customers':'Customers','documents':'Documents','error-log':'Error Log','field':'Field Work','fleet':'Fleet','inventory':'Inventory','jobs':'Jobs','measure':'Measure','money':'Money','payroll-prep':'Payroll Prep','people':'Team','price-book':'Price Book','proof-log':'Proof Log','quotes':'Quotes','reports':'Reports','schedule':'Schedule','service-subscriptions':'Service Plans','settings':'Settings','social':'Social','storage-providers':'Storage','tasks':'Tasks'};if(names[slug])return names[slug];return String(slug).replace(/-/g,' ').replace(/\b\w/g,function(c){return c.toUpperCase();});}
function renderSettings(){const users=records('users'),roles=records('roles'),providers=records('providers'),modules=state.snapshot.modules||[];$('mainContent').innerHTML=pageHead('Settings & Apps','Manage users, roles, app views, providers, offline storage and owner controls.')+`<div class="grid"><section class="card span5"><h2>Add business user</h2><form id="userForm"><label>Email</label><input name="email" type="email" required><label>Display name</label><input name="displayName"><label>Role</label><select name="roleId">${optionRows(roles,['Role ID'],row=>v(row,'Role Name'),'Select role')}</select><div class="actions"><button>Save user access</button></div></form><div class="list">${users.length?users.map(row=>`<div class="row"><div class="row-top"><strong>${esc(v(row,'Display Name','Email'))}</strong>${pill(v(row,'Status'))}</div><small>${esc(v(row,'Email'))} · ${esc(v(row,'Role ID'))}</small></div>`).join(''):empty('No users.')}</div></section><section class="card span4"><h2>Provider connections</h2><div class="list">${providers.map(row=>`<div class="row provider"><div><strong>${esc(v(row,'Provider Name'))}</strong><small>${esc(v(row,'Provider Type'))}</small></div>${pill(v(row,'Connection Status'),v(row,'Connection Status')==='Connected'?'good':'pending')}</div>`).join('')}</div><p class="muted small">Email, SMS, social and AI providers are connected per business. Credentials are never copied from one business to another.</p></section><section class="card span3"><h2>Installed modules</h2><div class="list">${modules.map(module=>`<div class="row"><strong>${esc(friendlyModuleName(module))}</strong></div>`).join('')}</div></section><section class="card span6"><h2>Business Profile</h2><div id="businessProfileSection"><p class="muted small">Loading business profile…</p></div></section><section class="card span6"><h2>Trade Package</h2><div id="tradePackageSection"><p class="muted small">Loading trade packages…</p></div></section><section class="card span12"><h2>Owner Controls</h2><div id="ownerControlsSection"></div></section><section class="card span6"><h2>App views</h2><div class="list">${Object.entries(SHELL_LABELS).map(([key,label])=>`<div class="row"><div class="row-top"><strong>${esc(label)}</strong><a class="app-view-open" href="./?shell=${key}">Open view</a></div><small>Uses the same business records and upgrade path.</small></div>`).join('')}</div></section><section class="card span6"><h2>Business setup &amp; onboarding</h2><p class="muted small">New to the Office, or setting up another business? Run the guided setup — business profile, services, customers, and team — or work through the setup checklist at your own pace. AI help is optional at every step and nothing saves without your approval.</p><div class="actions"><button type="button" data-h38-onboarding-open="onboarding">🧭 Start guided setup</button><button type="button" class="secondary" data-h38-onboarding-open="setupChecklist">✅ Open setup checklist</button><button type="button" class="secondary" data-h38-tour>🎓 Take the office tour</button></div></section><section class="card span6"><h2>Offline device</h2><p class="muted">Last synced: ${dateTime(state.snapshot.cachedAt)}</p><label>Sync server URL</label><input id="bridgeUrlSetting" value="${esc(state.bridge.url||BRIDGE_URL)}"><label><input id="settingsDrivingMode" type="checkbox" ${state.drivingMode?'checked':''}> Driving mode</label><div class="actions"><button id="saveLocalSettings">Save device settings</button><button id="clearDevice" class="danger">Clear this device</button></div>${serverSafeguard()}</section></div>`;bindForm('userForm',async(data,form)=>{requireValue(data.email,'Email is required.');await queueOperation('SAVE_USER','User',newId('USER'),data);form.reset();toast('User access queued. The user will only see this business after synchronization.');});$('saveLocalSettings').onclick=async()=>{const settings={id:'settings',bridgeUrl:$('bridgeUrlSetting').value.trim()||BRIDGE_URL,drivingMode:$('settingsDrivingMode').checked};await put('meta',settings);state.drivingMode=settings.drivingMode;state.bridge.setUrl(settings.bridgeUrl);toast('Device settings saved.');};$('clearDevice').onclick=async()=>{if(!confirm('Clear all Commercial Office data saved on this device? Server records will not be deleted.'))return;await clearAll();location.reload();};if(window.H38CustomerComms){try{
  var prof=window.H38CustomerComms.getBusinessProfile();
  $('businessProfileSection').innerHTML='<label>Business name</label><input id="bpBusinessName" value="'+prof.businessName.replace(/"/g,'&quot;')+'" disabled><label>Google Review Link</label><input id="bpReviewLink" type="url" placeholder="https://g.page/..." value="'+(prof.googleReviewLink||'').replace(/"/g,'&quot;')+'"><label>Facebook Review Link</label><input id="bpReviewLinkFb" type="url" placeholder="https://www.facebook.com/yourpage/reviews" value="'+(prof.facebookReviewLink||'').replace(/"/g,'&quot;')+'"><label>Yelp Review Link</label><input id="bpReviewLinkYelp" type="url" placeholder="https://www.yelp.com/biz/your-business" value="'+(prof.yelpReviewLink||'').replace(/"/g,'&quot;')+'"><p class="muted small">Used in review request texts. Requests rotate across the links you set (Google, then Facebook, then Yelp) so reviews spread out. Find them on each platform&#39;s business page.</p><label>Review request message</label><textarea id="bpReviewTemplate" rows="3" placeholder="Thanks for choosing [Business]! Would you mind leaving us a quick review? [Link]">'+esc(prof.reviewRequestTemplate||'')+'</textarea><p class="muted small">Placeholders: [Business], [Customer], [Link]. This is the exact text customers get.</p><label>Auto-send delay</label><select id="bpReviewDelay">'+window.H38CustomerComms.reviewDelayOptions().map(function(o){return '<option value="'+o.key+'"'+(o.key===(prof.reviewRequestDelay||'3h')?' selected':'')+'>'+esc(o.label)+'</option>';}).join('')+'</select><p class="muted small">Only applies when "Auto-send review requests" is on in Owner Controls. Texts never go out 9pm&ndash;8am.</p><div class="actions"><button id="saveReviewLink">Save review settings</button></div><h3>Recent review requests</h3><div class="list">'+(function(){var rows=window.H38CustomerComms.reviewRequestsLog(10);return rows.length?rows.map(function(r){return '<div class="row"><div class="row-top"><strong>'+esc(r.to||'—')+'</strong>'+pill(r.status)+'</div><small>'+esc(r.purpose)+(r.sentAt?' · '+esc(r.sentAt):'')+(r.deliverAfter?' · after '+esc(r.deliverAfter):'')+'</small></div>';}).join(''):empty('No review requests sent yet.');})()+'</div>';
  $('saveReviewLink').onclick=function(){window.H38CustomerComms.saveReviewLinks({google:$('bpReviewLink').value.trim(),facebook:$('bpReviewLinkFb').value.trim(),yelp:$('bpReviewLinkYelp').value.trim()});window.H38CustomerComms.saveReviewTemplate($('bpReviewTemplate').value);window.H38CustomerComms.saveReviewDelay($('bpReviewDelay').value);toast('Review settings saved.');};
}catch(e){$('businessProfileSection').innerHTML='<p class="muted">Business profile unavailable.</p>';}}
if(window.H38OwnerControls){$('ownerControlsSection').innerHTML=window.H38OwnerControls.render();window.H38OwnerControls.bind();}
renderTradePackageSection();}

function renderTradePackageSection(){
  const section=$('tradePackageSection');
  if(!section)return;
  if(!window.H38TradePackages){
    section.innerHTML='<p class="muted">Trade packages unavailable.</p>';
    return;
  }
  const loaded=window.H38TradePackages.getLoaded();
  const list=window.H38TradePackages.list();
  section.innerHTML=
    (loaded
      ? `<p><strong>Active package:</strong> ${esc(loaded.tradeName)} <span class="muted small">(loaded ${esc((loaded.loadedAt||'').slice(0,10))})</span></p>`
      : `<p class="muted">No trade package loaded. Pick one below to pre-fill your price book, checklists, job types, and quote language.</p>`)
    + `<label>Trade</label><select id="tradePackageSelect">`
    + list.map(t=>`<option value="${esc(t.id)}"${loaded&&loaded.tradeId===t.id?' selected':''}>${esc(t.name)} — ${t.items} price book items</option>`).join('')
    + `</select>`
    + `<div class="actions" style="margin-top:8px"><button id="loadTradePackageBtn">Load package</button></div>`
    + `<p class="muted small">Loading adds new price book items (existing SKUs are skipped). You can edit or delete everything afterwards.</p>`;
  $('loadTradePackageBtn').onclick=async()=>{
    const tradeId=$('tradePackageSelect').value;
    const btn=$('loadTradePackageBtn');
    btn.disabled=true;btn.textContent='Loading…';
    try{
      const result=await window.H38TradePackages.load(tradeId);
      toast(`Trade package loaded: ${result.added} price book items added${result.skipped?` (${result.skipped} already present)`:''}.`);
      renderTradePackageSection();
    }catch(e){
      toast('Package load failed: '+(e.message||e),true);
      btn.disabled=false;btn.textContent='Load package';
    }
  };
}

function parseJson(value,fallback={}){try{return value?JSON.parse(value):fallback;}catch{return fallback;}}
function readMyDay(){const btn=document.getElementById('readDayButton');if(btn){btn.disabled=true;btn.textContent='Reading...';setTimeout(()=>{btn.disabled=false;btn.textContent='Read my day';},3000);}const events=records('scheduleEvents').filter(row=>new Date(v(row,'Start Time')).getTime()>=Date.now()-2*3600000).sort((a,b)=>new Date(v(a,'Start Time'))-new Date(v(b,'Start Time'))).slice(0,5),tasks=records('tasks').filter(row=>['OPEN','ACCEPTED','STARTED','WAITING','BLOCKED'].includes(String(v(row,'Status')).toUpperCase())).slice(0,5);let text=events.length?`You have ${events.length} upcoming schedule items. `+events.map(row=>`${v(row,'Title')} at ${new Date(v(row,'Start Time')).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}`).join('. '):'You have no upcoming schedule items in the cached pack.';if(tasks.length)text+=` You also have ${tasks.length} open tasks.`;speak(text);toast(text);}
function speak(text){if(!('speechSynthesis'in window)||!text)return;window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(String(text).slice(0,1500));utterance.rate=1;window.speechSynthesis.speak(utterance);}
function toggleVoice(){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){toast('Voice recognition is not available in this browser. You can still use voice notes through the phone keyboard.',true);return;}if(state.listening){state.recognition?.stop();return;}const recognition=new Recognition();state.recognition=recognition;recognition.lang='en-US';recognition.interimResults=false;recognition.maxAlternatives=1;recognition.onstart=()=>{state.listening=true;$('voiceButton').classList.add('voice-listening');toast('Listening…');};recognition.onend=()=>{state.listening=false;$('voiceButton').classList.remove('voice-listening');};recognition.onerror=event=>toast(`Voice error: ${event.error}`,true);recognition.onresult=event=>handleVoiceTranscript(event.results[0][0].transcript);recognition.start();}
;

