'use strict';

Object.assign(PAGE_DEFS,{
  people:['👷','People'],
  accounting:['📚','Accounting'],
  payroll:['🧮','Payroll'],
  tax:['🗂️','Tax Prep'],
  controls:['🛡️','Controls'],
  reports:['📊','Reports'],
  onboarding:['🧭','Business Onboarding'],
  setupChecklist:['✅','Setup Checklist']
});
